 public static void BuildAll(){BuildScene();string dir=Path.GetFullPath(Application.dataPath+"/../../Builds/Windows");Directory.CreateDirectory(dir);var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{"Assets/Scenes/FirstLight.unity"},locationPathName=Path.Combine(dir,"LightFeast.exe"),target=BuildTarget.StandaloneWindows64,options=BuildOptions.None});File.WriteAllText(Path.GetFullPath(Application.dataPath+"/../../Validation/build-result.json"),"{\"result\":\""+result.summary.result+"\",\"errors\":"+result.summary.totalErrors+",\"warnings\":"+result.summary.totalWarnings+",\"bytes\":"+result.summary.totalSize+"}");if(result.summary.result!=BuildResult.Succeeded)throw new Exception("Build failed: "+result.summary.result);Debug.Log("FIRST_LIGHT_BUILD_SUCCEEDED");}
 static void Layer(string name,int index){var tag=new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0]);tag.FindProperty("layers").GetArrayElementAtIndex(index).stringValue=name;tag.ApplyModifiedProperties();}
 static Material MaterialAsset(string name,string shader){var m=new Material(Shader.Find(shader)){name=name};string path="Assets/Materials/"+name+".mat";AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(m,path);return m;}
 static GameObject Card(string name,Transform parent,Vector3 pos,float width,float height,string file,Rect crop,float tw,float th,int nx=1,int ny=1){
  var go=new GameObject(name);go.transform.SetParent(parent,false);go.transform.localPosition=pos;var mesh=Grid(name,width,height,crop,tw,th,nx,ny);go.AddComponent<MeshFilter>().sharedMesh=mesh;var mat=MaterialAsset(name,"LightFeast/PaintedLayer");mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Art+file);go.AddComponent<MeshRenderer>().sharedMaterial=mat;return go;}
 static Mesh Grid(string name,float width,float height,Rect c,float tw,float th,int nx,int ny){var m=new Mesh{name=name};var v=new Vector3[(nx+1)*(ny+1)];var uv=new Vector2[v.Length];var t=new int[nx*ny*6];var colours=new Color[v.Length];for(int y=0;y<=ny;y++)for(int x=0;x<=nx;x++){int i=y*(nx+1)+x;float u=(float)x/nx,f=(float)y/ny;v[i]=new Vector3(u*width,f*height,0);uv[i]=new Vector2((c.x+u*c.width)/tw,1-(c.y+(1-f)*c.height)/th);colours[i]=Color.white;}int k=0;for(int y=0;y<ny;y++)for(int x=0;x<nx;x++){int i=y*(nx+1)+x;t[k++]=i;t[k++]=i+nx+1;t[k++]=i+1;t[k++]=i+1;t[k++]=i+nx+1;t[k++]=i+nx+2;}m.vertices=v;m.uv=uv;m.colors=colours;m.triangles=t;m.RecalculateNormals();m.RecalculateBounds();string path=Geo+name+".asset";AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(m,path);return m;}
 static GameObject Glow(string name,Transform parent,Vector3 pos,Vector2 size,Color color){var go=new GameObject(name);go.transform.SetParent(parent,false);go.transform.localPosition=pos;go.AddComponent<MeshFilter>().sharedMesh=Grid(name,size.x,size.y,new Rect(0,0,1,1),1,1,1,1);var vertices=go.GetComponent<MeshFilter>().sharedMesh.vertices;for(int i=0;i<vertices.Length;i++)vertices[i]-=new Vector3(size.x/2,size.y/2,0);go.GetComponent<MeshFilter>().sharedMesh.vertices=vertices;go.GetComponent<MeshFilter>().sharedMesh.RecalculateBounds();var mat=MaterialAsset(name,"LightFeast/SoftLight");mat.SetFloat("_Radial",1);mat.SetColor("_Color",color);go.AddComponent<MeshRenderer>().sharedMaterial=mat;return go;}
 static LineRenderer Beam(string name,Transform parent,float width,Color c){var go=new GameObject(name);go.transform.SetParent(parent);var l=go.AddComponent<LineRenderer>();l.positionCount=2;l.useWorldSpace=true;l.widthMultiplier=width;l.numCapVertices=4;l.alignment=LineAlignment.View;var mat=MaterialAsset(name,"LightFeast/SoftLight");mat.SetColor("_Color",c);l.sharedMaterial=mat;l.startColor=l.endColor=Color.white;return l;}
 static ParticleSystem Particles(string name,Transform parent,Vector3 pos,float rate,Color color,float size){var go=new GameObject(name);go.transform.SetParent(parent,false);go.transform.localPosition=pos;var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.startLifetime=new ParticleSystem.MinMaxCurve(.5f,1.4f);main.startSpeed=new ParticleSystem.MinMaxCurve(.08f,.3f);main.startSize=new ParticleSystem.MinMaxCurve(size*.4f,size);main.startColor=color;main.simulationSpace=ParticleSystemSimulationSpace.World;main.maxParticles=96;main.playOnAwake=true;var e=ps.emission;e.rateOverTime=rate;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Sphere;shape.radius=.12f;var vel=ps.velocityOverLifetime;vel.enabled=true;vel.space=ParticleSystemSimulationSpace.World;vel.y=.14f;var col=ps.colorOverLifetime;col.enabled=true;var grad=new Gradient();grad.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(new Color(1,.61f,.2f),1)},new[]{new GradientAlphaKey(.75f,0),new GradientAlphaKey(0,1)});col.color=grad;var mat=MaterialAsset(name,"LightFeast/SoftLight");mat.SetFloat("_Radial",1);mat.SetColor("_Color",Color.white);ps.GetComponent<ParticleSystemRenderer>().sharedMaterial=mat;return ps;}
