  var go=new GameObject(name);go.transform.SetParent(foreground);go.transform.position=pos;var m=new Mesh{name=name};m.vertices=new[]{new Vector3(-.5f,0,0),new Vector3(.5f,0,0),new Vector3(.43f,.75f,0),new Vector3(.24f,1,0),new Vector3(-.35f,.9f,0),new Vector3(-.5f,.5f,0)};var v=m.vertices;for(int i=0;i<v.Length;i++)v[i]=Vector3.Scale(v[i],size);m.vertices=v;m.triangles=new[]{0,2,1,0,3,2,0,4,3,0,5,4};m.uv=new[]{new Vector2(.35f,.3f),new Vector2(.4f,.3f),new Vector2(.4f,.4f),new Vector2(.38f,.44f),new Vector2(.35f,.43f),new Vector2(.34f,.35f)};m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.DeleteAsset(Geo+name+".asset");AssetDatabase.CreateAsset(m,Geo+name+".asset");go.AddComponent<MeshFilter>().sharedMesh=m;var mat=MaterialAsset(name,"LightFeast/PaintedLayer");mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Art+"l1-ground.png");go.AddComponent<MeshRenderer>().sharedMaterial=mat;
